local UIMazeShopEventDialog = Class("UIMazeShopEventDialog")

function UIMazeShopEventDialog:__init() 
    self.goods = nil
    self.point = nil
    self.goodsArr = {}
    self.goodType = nil      --商品道具的类型   是迷宫还是正常道具
    self._itemLoader = nil
end

function UIMazeShopEventDialog:__delete()
    self.goods = nil
    self.point = nil
    self.goodsArr = {}
    self.goodType = nil
    self._itemLoader = nil
end

function UIMazeShopEventDialog:OnFocus(focus)
end

function UIMazeShopEventDialog:Awake()
    local pars = self.controller.Argument.parameters   --界面传参
    self.point = pars.point
    if not self.point then return end
    self.goods = self.point.goods
    if not self.goods then return end

    self:SetGoodArr()
    self:FillSelfCf()

    --神秘商店
    if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
        CfUtils.FillText(self.cfText1, localize("珍惜物品抄底价打折，抓紧机会购买吧"))
        self.goodType = Constants.IDArea.Goods
        self:FillMysteriousShop()
    elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
        CfUtils.FillText(self.cfText1, localize("尽情购物吧"))
        self.goodType = Constants.IDArea.Maze
        self:FillCommonShop()
    else
        return
    end

    SetButtonAction(self.alls, Bind(self, self.OnAllsBtn))
end

function UIMazeShopEventDialog:OnFocus(focus)
    if focus then
        self:SetTopCommon()
    end
end

function UIMazeShopEventDialog:OnAllsBtn()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMazeBagDialog, nil})
end

function UIMazeShopEventDialog:FillSelfCf()
    self:FillTitle()
    SetButtonAction(self.btnBuyOver, Bind(self, self.OnbtnBuyOver))
    SetButtonAction(self.btnClose, Bind(self, self.OnbtnClose))

    CfUtils.FillText(self.btnBuyOver.transform:Find("Text"), localize("结束购物"))
    CfUtils.FillText(self.btnBuy.transform:Find("Text"), localize("购买"))
end

--神秘商店
function UIMazeShopEventDialog:FillMysteriousShop()
    self.saleGoodView:InitGridView(#self.goodsArr, function(loopView, index)
        if index < 0 or index > #self.goodsArr - 1 then 
            return nil
        end

        local itemGo = loopView:NewListViewItem("saleGood")
        local goodInfo = self.goodsArr[index + 1]

        local scr = CfUtils.GetLuaScr(itemGo, UIMazeShopEventMysteriousNode)
        if scr then
            scr:Refresh(goodInfo, self.goodType, function()
                self:FillItemShow(goodInfo, index + 1)
            end)
        end

        return itemGo
    end)

    KTool.SetActive(self.saleGoodView, true)
    KTool.SetActive(self.goodView, false)
end

--普通商店
function UIMazeShopEventDialog:FillCommonShop()
    self.goodView:InitGridView(#self.goodsArr, function(loopView, index)
        if index < 0 or index > #self.goodsArr - 1 then 
            return nil
        end

        local itemGo = loopView:NewListViewItem("good")
        local goodInfo = self.goodsArr[index + 1]

        local scr = CfUtils.GetLuaScr(itemGo, UIMazeShopEventCommonNode)
        if scr then
            scr:Refresh(goodInfo, self.goodType, function()
                self:FillItemShow(goodInfo, index + 1)
            end)
        end
        return itemGo
    end)
    KTool.SetActive(self.saleGoodView, false)
    KTool.SetActive(self.goodView, true)
end

function UIMazeShopEventDialog:RefeshShopList()
    local a = self.goodsArr
    if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
        GameUtils.ReloadData(self.saleGoodView, table.count(self.goodsArr))
    elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
        GameUtils.ReloadData(self.goodView, table.count(self.goodsArr))
    end
end

function UIMazeShopEventDialog:FillTitle()
    CfUtils.FillText(self.curPointText, checkNumber(self.point.line) < 10 -1  and "0"..self.point.line - 1 or self.point.line - 1)
    CfUtils.FillText(self.allPointText, "/"..MazeMapMgr:GetInstance():GetMaxLineNum())

    local eventType = self.point.type
    CfUtils.FillText(self.name, CfUtils.GetCfData(AutoIds.IdSetting351, self.point.type, Constants.Tab_MazeEventType.name))
    self.img.color = CfUtils.GetMazeCommonColor(self.point.type)
    CfUtils.FillImage(self.typeImg, CfUtils.GetMazePreviewPath(self.point))
    self.loader = CfUtils.FillEnentAnim(self.typeImg, self.point)
end

--绘制商品展示
function UIMazeShopEventDialog:FillItemShow(good, index)
    local mazeGoodVo
    if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
        mazeGoodVo = CfUtils.GetCfVo(AutoIds.IdSetting363, "MazeGoodsVo", good.id)
    elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
        mazeGoodVo = CfUtils.GetCfVo(AutoIds.IdSetting364, "MazeGoodsVo", good.id)
    end
    if not mazeGoodVo then return end

    if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(mazeGoodVo.itemId)
        if vo then
            CfUtils.FillText(self.itemName, vo.name)
            CfUtils.FillText(self.desc, vo.desc)
        end
    elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
        CfUtils.FillText(self.itemName, mazeGoodVo.name)
        CfUtils.FillText(self.desc, mazeGoodVo.desc)
    end

    CfUtils.FillText(self.price, mazeGoodVo.newPrice)
    CfUtils.FillText(self.cfText, localize("小计"))
    CfUtils.FillText(self.buyNum, "x"..good.num)

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end
    if self._itemLoader.IsSuccess then
        local go = self.item.transform:Find("item")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, self.item)
            go.name = "item"
        end
        if go then
            CfUtils.RefeshGoodGo(go, mazeGoodVo.itemId, nil, 0.9, self.goodType)
        end
    end

    local currency = GoodsConfMgr:GetInstance():GetGoodsVoById(mazeGoodVo.goodsConsum)
    if currency then
        CfUtils.FillImage(self.consumeItem2, currency.photoPath)
    end

    SetButtonAction(self.btnBuy, function()
        local consumeNum = 0
        if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
            consumeNum = GoodsUtils.GetThingNo(checkNumber(mazeGoodVo.goodsConsum))
        elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
            consumeNum = MazeMgr:GetInstance():GetMazeCurrencyNum()
        end

        if checkNumber(consumeNum) < checkNumber(mazeGoodVo.newPrice) then
            GameUtils.Toast(localize("_num_不足", {_num_ = currency.name}))
            return
        end

        MazeMgr:GetInstance():MazeMoveToBuy(self.point, good.id, function(jsonData)
            self.goodsArr[index].num = 0
            KTool.SetActive(self.GoodDesShow, false)
            
            --神秘商店进 外面的背包
            if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })
                GoodsUtils.DrawRewards(jsonData.rewards)
                --扣砖石
                GoodsUtils.DrawRewards({
                    [1] = {
                        goodsId = mazeGoodVo.goodsConsum,
                        num = -(mazeGoodVo.newPrice),
                    }
                })
            --普通商店进迷宫的背包
            elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
                local mazeBagComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeBagComponent, Constants.MazeBagEntityId)
                local rewards = jsonData.mazeGoods
                if rewards then
                    for k, v in pairs(rewards) do
                        mazeBagComp:Additem(v, Constants.IDType.MazeItem)
                        v.idAreaType = Constants.IDArea.Maze
                    end
                end
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })

                --扣迷宫币
                MazeMgr:GetInstance():SetMazeCurrencyNum(MazeMgr:GetInstance():GetMazeCurrencyNum() - mazeGoodVo.newPrice)
            end

            self:RefeshShopList()
        end)
    end)

    KTool.SetActive(self.GoodDesShow, true)
end

function UIMazeShopEventDialog:SetGoodArr()
    for k, v in pairs(self.goods) do
        table.insert(self.goodsArr, {
            id = checkNumber(k),    --商品id
            num = checkNumber(v)
        })
    end

    local goodType
    if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
        goodType = Constants.IDArea.Goods
    elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
        goodType = Constants.IDArea.Maze
    end
    --品质从低至高
    table.sort(self.goodsArr, function(a, b)
        local item1
        local item2
        if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
            local goodVo = CfUtils.GetCfVo(AutoIds.IdSetting363, "MazeGoodsVo", a.id)
            if goodVo then
                item1 = GoodsConfMgr:GetInstance():GetGoodsVoById(goodVo.itemId)
            end

            goodVo = CfUtils.GetCfVo(AutoIds.IdSetting363, "MazeGoodsVo", b.id)
            if goodVo then
                item2 = GoodsConfMgr:GetInstance():GetGoodsVoById(goodVo.itemId)
            end
        elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
            local goodVo = CfUtils.GetCfVo(AutoIds.IdSetting364, "MazeGoodsVo", a.id)
            if goodVo then
                item1 = GoodsConfMgr:GetInstance():GetGoodsVoById(goodVo.itemId, Constants.IDArea.Maze)
            end

            goodVo = CfUtils.GetCfVo(AutoIds.IdSetting364, "MazeGoodsVo", b.id)
            if goodVo then
                item2 = GoodsConfMgr:GetInstance():GetGoodsVoById(goodVo.itemId, Constants.IDArea.Maze)
            end
        end

        if item1 and item2 then
            return checkNumber(item1.quality) < checkNumber(item2.quality)
        end
        return false
    end)
end

--结束购买
