end

function UIMazeShopEventDialog:Close()
    MazeMgr:GetInstance():OpenMazeMainGameObject()
    UIModule.CloseDialog(self.controller)
end

function UIMazeShopEventDialog:SetTopCommon()
    CfUtils.RefreshTopCommon(function()
        self:Close()
    end, true)
    --神秘商店
    if checkNumber(self.point.type) == Constants.MazePointType.MysteriousShop then
        GameUtils.UpdateNavBarShowGoods({Constants.Currency.FreeDiamondId})
    elseif checkNumber(self.point.type) == Constants.MazePointType.CommonShop then   --普通商店
        GameUtils.UpdateNavBarShowGoods({Constants.Currency.MazeCurrency})
    end
end

